/// (case index, unit index, unit): lone surrogate halves in the TS text.
const LONE_UNITS: &[(usize, usize, u16)] = &[(25, 40, 0xd83d), (26, 40, 0xd83d)];

fn excerpt(body: &str, terms: &[&str], max_chars: Option<usize>, single_line: bool) -> Excerpt {
    let terms: Vec<String> = terms.iter().map(|term| (*term).to_owned()).collect();
    build_excerpt(
        body,
        &terms,
        ExcerptOptions {
            max_chars,
            single_line,
        },
    )
}

fn pairs(excerpt: &Excerpt) -> Vec<(usize, usize)> {
    excerpt
        .highlights
        .iter()
        .map(|range| (range.start, range.end))
        .collect()
}

/// Highlights are sorted, non-empty, apart, and inside the text.
fn assert_well_formed(excerpt: &Excerpt) {
    let mut previous_end = 0;
    for range in &excerpt.highlights {
        assert!(range.start < range.end, "{range:?}");
        assert!(range.start >= previous_end, "{range:?}");
        assert!(range.end <= excerpt.text.len(), "{range:?}");
        previous_end = range.end;
    }
}

#[test]
fn every_case_matches_the_typescript() {
    for (body, terms, max_chars, single_line, text, highlights) in CASES {
        let built = excerpt(body, terms, *max_chars, single_line.unwrap_or(true));
        // A window edge can split a surrogate pair. Lossy decoding turns the
        // lone half into U+FFFD, one unit, as toWellFormed() did in the generator;
        // `split_surrogates_keep_the_same_half` checks which half it was.
        assert_eq!(
            String::from_utf16_lossy(&built.text),
            *text,
            "text of {body:?}"
        );
        assert_eq!(
            built.text.len(),
            text.encode_utf16().count(),
            "length of {body:?}"
        );
        assert_eq!(pairs(&built), *highlights, "highlights of {body:?}");
        assert_well_formed(&built);
    }
}

#[test]
fn split_surrogates_keep_the_same_half() {
    for &(case, at, unit) in LONE_UNITS {
        let (body, terms, max_chars, single_line, _, _) =
            CASES.get(case).copied().unwrap_or_default();
        let built = excerpt(body, terms, max_chars, single_line.unwrap_or(true));
        assert_eq!(
            built.text.get(at).copied(),
            Some(unit),
            "unit {at} of {body:?}"
        );
    }
    // Every U+FFFD in the expected text is a lone half pinned above.
    let replaced: usize = CASES
        .iter()
        .map(|case| case.4.matches('\u{fffd}').count())
        .sum();
    assert_eq!(replaced, LONE_UNITS.len());
}

#[test]
fn defaults_match_the_typescript() {
    assert_eq!(EXCERPT_MIN_CHARS, 40);
    assert_eq!(EXCERPT_DEFAULT_CHARS, 240);
    let options = ExcerptOptions::default();
    assert_eq!(options.max_chars, None);
    assert!(options.single_line);
}

#[test]
fn highlights_cover_the_matched_text() {
    let built = excerpt("Graph neural networks on GRAPHS", &["graph"], None, true);
    let words: Vec<String> = built
        .highlights
        .iter()
        .map(|ExcerptRange { start, end }| {
            String::from_utf16_lossy(built.text.get(*start..*end).unwrap_or_default())
        })
        .collect();
    assert_eq!(words, ["Graph", "GRAPH"]);
}

#[test]
fn a_cut_window_is_marked_with_ellipses() {
    let body = format!("{}needle{}", "x ".repeat(100), " y".repeat(100));
    let built = excerpt(&body, &["needle"], Some(40), true);
    assert_eq!(built.text.first(), Some(&0x2026));
    assert_eq!(built.text.last(), Some(&0x2026));
    assert_eq!(built.text.len(), 42);
    assert_eq!(built.highlights.len(), 1);
}

#[test]
fn empty_and_blank_bodies_give_an_empty_excerpt() {
    for body in ["", " ", "\u{a0}\u{feff}\n"] {
        assert_eq!(excerpt(body, &["x"], None, true), Excerpt::default());
        assert_eq!(excerpt(body, &["x"], None, false), Excerpt::default());
    }
}

/// Bodies with case-changing letters, astral chars and JS whitespace.
fn body_text() -> impl Strategy<Value = String> {
    r"(ab|AB|x|é|É|İ|Σ|σ|ς|ß|\x{212a}|\x{1f600}| |  |\n|\x{a0}|\x{feff}){0,60}"
}

fn term_text() -> impl Strategy<Value = String> {
    r"(ab|a|b|x|é|İ|i\x{307}|σ|Σ|\x{1f600}| ){0,4}"
}

proptest! {
    #[test]
    fn excerpts_are_well_formed(
        body in body_text(),
        terms in prop::collection::vec(term_text(), 0..4),
        max_chars in prop::option::of(0usize..80),
        single_line in any::<bool>(),
    ) {
        let built = build_excerpt(&body, &terms, ExcerptOptions { max_chars, single_line });
        let span = max_chars.unwrap_or(EXCERPT_DEFAULT_CHARS).max(EXCERPT_MIN_CHARS);
        prop_assert!(built.text.len() <= span + 2);
        assert_well_formed(&built);
    }

    #[test]
    fn arbitrary_input_never_panics(body in any::<String>(), term in any::<String>()) {
        let built = build_excerpt(&body, &[term], ExcerptOptions::default());
        prop_assert!(built.text.len() <= EXCERPT_DEFAULT_CHARS + 2);
    }
}
